<?php
namespace App\Http\Controllers\Api\V1\Guest;
use App\Http\Controllers\Controller; use App\Models\{BookingAddon,DigitalCheckin,GuestDevice,GuestNotification,LaundryService,LoyaltyAccount,MenuItem,Outlet,PropertyWebSetting,Reservation,GuestServiceRequest,RoomType}; use App\Services\Guest\OnlineBookingService; use App\Services\Reservations\AvailabilityService; use Carbon\Carbon; use Illuminate\Http\Request;
class GuestPortalController extends Controller { private function guest(Request $r){abort_unless($r->user()->role==='guest'&&$r->user()->guest_id,403);return $r->user()->guest;}
public function home(Request $r){$g=$this->guest($r);return ['guest'=>$g,'loyalty'=>LoyaltyAccount::with('tier')->where('guest_id',$g->id)->first(),'upcoming'=>Reservation::with('rooms.roomType')->where('guest_id',$g->id)->where('check_out_at','>=',now())->orderBy('check_in_at')->limit(5)->get(),'unread_notifications'=>GuestNotification::where('guest_id',$g->id)->whereNull('read_at')->count()];}
public function roomTypes(Request $r,AvailabilityService $a){$g=$this->guest($r);$in=Carbon::parse($r->validate(['check_in'=>'required|date','check_out'=>'required|date|after:check_in'])['check_in'])->setTime(14,0);$out=Carbon::parse($r->input('check_out'))->setTime(11,0);$ids=$a->availableRoomIds($g->property_id,$in,$out);return RoomType::where('property_id',$g->property_id)->whereHas('rooms',fn($q)=>$q->whereIn('id',$ids))->withCount(['rooms as available_count'=>fn($q)=>$q->whereIn('id',$ids)])->get();}
public function addons(Request $r){$g=$this->guest($r);return BookingAddon::where('property_id',$g->property_id)->where('is_active',1)->get();}
public function book(Request $r,OnlineBookingService $s){$g=$this->guest($r);$d=$r->validate(['room_type_id'=>'required|integer','check_in'=>'required|date|after_or_equal:today','check_out'=>'required|date|after:check_in','adults'=>'required|integer|min:1','children'=>'nullable|integer|min:0','special_requests'=>'nullable|string','addons'=>'nullable|array']);$web=PropertyWebSetting::where('property_id',$g->property_id)->first();$d+=['property_id'=>$g->property_id,'first_name'=>$g->first_name,'last_name'=>$g->last_name,'email'=>$g->email,'phone'=>$g->phone,'nationality'=>$g->nationality,'deposit_percent'=>$web?->default_deposit_percent??30];return response()->json($s->create($d),201);}
public function bookings(Request $r){$g=$this->guest($r);return Reservation::with(['rooms.roomType','rooms.room','payments'])->where('guest_id',$g->id)->latest('check_in_at')->paginate(20);}
public function digitalCheckin(Request $r,Reservation $reservation){$g=$this->guest($r);abort_unless($reservation->guest_id===$g->id,403);$d=$r->validate(['id_type'=>'nullable|string|max:50','id_number'=>'nullable|string|max:120','vehicle_registration'=>'nullable|string|max:50','arrival_notes'=>'nullable|string|max:1000','terms_accepted'=>'accepted']);return DigitalCheckin::updateOrCreate(['reservation_id'=>$reservation->id],$d+['property_id'=>$reservation->property_id,'guest_id'=>$g->id,'status'=>'submitted','submitted_at'=>now()]);}
public function services(Request $r){$g=$this->guest($r);return ['restaurant_outlets'=>Outlet::where('property_id',$g->property_id)->where('is_active',1)->get(),'menu'=>MenuItem::where('property_id',$g->property_id)->where('is_active',1)->limit(100)->get(),'laundry'=>LaundryService::where('property_id',$g->property_id)->where('is_active',1)->get()];}
public function requestService(Request $r){$g=$this->guest($r);$d=$r->validate(['stay_id'=>'nullable|integer','room_id'=>'nullable|integer','request_type'=>'required|string|max:60','details'=>'nullable|string|max:1000','priority'=>'nullable|in:low,normal,high,urgent']);return GuestServiceRequest::create($d+['property_id'=>$g->property_id,'guest_id'=>$g->id,'status'=>'new','requested_at'=>now()]);}
public function loyalty(Request $r){$g=$this->guest($r);return LoyaltyAccount::with(['tier','transactions'=>fn($q)=>$q->latest()->limit(30)])->where('guest_id',$g->id)->first();}
public function notifications(Request $r){$g=$this->guest($r);return GuestNotification::where('guest_id',$g->id)->latest()->paginate(30);} public function readNotification(Request $r,GuestNotification $notification){$g=$this->guest($r);abort_unless($notification->guest_id===$g->id,403);$notification->update(['read_at'=>now()]);return $notification;}
public function device(Request $r){$g=$this->guest($r);$d=$r->validate(['platform'=>'required|in:android,ios','device_name'=>'nullable|string|max:120','push_token'=>'nullable|string|max:2000','app_version'=>'nullable|string|max:40']);return GuestDevice::updateOrCreate(['guest_id'=>$g->id,'push_token'=>$d['push_token']??null],$d+['last_seen_at'=>now()]);}
}
